window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1dd8938396b8a97d"]={"versions": [{"id": "FIG-1dd8938396b8a97d", "releases": ["R22-11", "R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles AUTOSAR-Metamodell-Diagramm zur Darstellung von Datenmodellierungs- und Nachverfolgbarkeitsregeln (Data Type Tracing) zwischen der plattformunabhängigen Abstraktionsebene (Abstract Platform) und den plattformspezifischen Domänen (Classic Platform / Adaptive Platform). Die Abbildung veranschaulicht anhand eines Gegenüberstellungsvergleichs zulässige Mappings über Zwischenschichten im Vergleich zu unzulässigem direktem Tracing.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die linke Konfiguration zeigt drei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Abstract Platform / ApplicationDataType</code> (oben)\n</li><li><code>Classic/Adaptive Platform / ApplicationDataType</code> (Mitte, rot hervorgehobene Box und Beschriftung)\n</li><li><code>Classic/Adaptive Platform / AbstractImplementationDataType</code> (unten)\n</li></ul>\n<p class=\"fig-p\">Verbindungen links:</p>\n<ul class=\"fig-list\"><li>Bidirektionale gestrichelte Tracing-Beziehung (<code>&lt;&lt;tracing&gt;&gt;</code>) zwischen <code>Abstract Platform / ApplicationDataType</code> und <code>Classic/Adaptive Platform / ApplicationDataType</code>.\n</li><li>Bidirektionale durchgezogene Zuordnung (<code>DataTypeMap</code>) zwischen <code>Classic/Adaptive Platform / ApplicationDataType</code> und <code>Classic/Adaptive Platform / AbstractImplementationDataType</code>.\n</li></ul>\n<p class=\"fig-p\">Die rechte Konfiguration zeigt zwei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Abstract Platform / ApplicationDataType</code> (oben)\n</li><li><code>Classic/Adaptive Platform / AbstractImplementationDataType</code> (unten)\n</li></ul>\n<p class=\"fig-p\">Verbindung rechts:</p>\n<ul class=\"fig-list\"><li>Rot gestrichelter Doppelpfeil mit einem roten Blitzsymbol, stereotypt annotiert mit <code>&lt;&lt;tracing&gt;&gt;</code>, der das unzulässige direkte Tracing zwischen <code>Abstract Platform / ApplicationDataType</code> und <code>Classic/Adaptive Platform / AbstractImplementationDataType</code> kennzeichnet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Metamodell-Schema ohne zeitlichen Ablauf oder Interaktionssequenzen. Es definiert strukturelle Mapping-Pfade für die Modelltransformation und Tracing-Validierung: Tracing verläuft stets typkonform zwischen korrespondierenden Abstraktionsebenen (<code>ApplicationDataType</code>), woran sich plattformintern die Auflösung via <code>DataTypeMap</code> anschließt. Ein direkter Brückenschlag unter Umgehung des plattformspezifischen <code>ApplicationDataType</code> ist ungültig.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel für AUTOSAR-Modellierer und Toolchain-Entwickler: Ein plattformunabhängiger <code>ApplicationDataType</code> der Abstract Platform darf nicht direkt auf einen plattformspezifischen <code>AbstractImplementationDataType</code> der Classic oder Adaptive Platform zurückgeführt werden (<code>&lt;&lt;tracing&gt;&gt;</code> verboten). Die Spezifikation erzwingt zwingend den Zwischenschritt über den plattformspezifischen <code>ApplicationDataType</code> und die anschließende plattformspezifische Typabbildung mittels <code>DataTypeMap</code>. Modell-Prüfwerkzeuge müssen direkte Tracing-Relationen zwischen abstrakten Anwendungsdatentypen und konkreten Implementierungsdatentypen als Konformitätsfehler ablehnen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-617f2be197133249", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles AUTOSAR-Metamodell-Diagramm zur Darstellung von Datenmodellierungs- und Nachverfolgbarkeitsregeln (Data Type Tracing) zwischen der plattformunabhängigen Abstraktionsebene (Abstract Platform) und den plattformspezifischen Domänen (Classic Platform / Adaptive Platform). Die Abbildung veranschaulicht anhand eines Gegenüberstellungsvergleichs zulässige Mappings über Zwischenschichten im Vergleich zu unzulässigem direktem Tracing.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die linke Konfiguration zeigt drei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Abstract Platform / ApplicationDataType</code> (oben)\n</li><li><code>Classic/Adaptive Platform / ApplicationDataType</code> (Mitte, rot hervorgehobene Box und Beschriftung)\n</li><li><code>Classic/Adaptive Platform / AbstractImplementationDataType</code> (unten)\n</li></ul>\n<p class=\"fig-p\">Verbindungen links:</p>\n<ul class=\"fig-list\"><li>Bidirektionale gestrichelte Tracing-Beziehung (<code>&lt;&lt;tracing&gt;&gt;</code>) zwischen <code>Abstract Platform / ApplicationDataType</code> und <code>Classic/Adaptive Platform / ApplicationDataType</code>.\n</li><li>Bidirektionale durchgezogene Zuordnung (<code>DataTypeMap</code>) zwischen <code>Classic/Adaptive Platform / ApplicationDataType</code> und <code>Classic/Adaptive Platform / AbstractImplementationDataType</code>.\n</li></ul>\n<p class=\"fig-p\">Die rechte Konfiguration zeigt zwei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Abstract Platform / ApplicationDataType</code> (oben)\n</li><li><code>Classic/Adaptive Platform / AbstractImplementationDataType</code> (unten)\n</li></ul>\n<p class=\"fig-p\">Verbindung rechts:</p>\n<ul class=\"fig-list\"><li>Rot gestrichelter Doppelpfeil mit einem roten Blitzsymbol, stereotypt annotiert mit <code>&lt;&lt;tracing&gt;&gt;</code>, der das unzulässige direkte Tracing zwischen <code>Abstract Platform / ApplicationDataType</code> und <code>Classic/Adaptive Platform / AbstractImplementationDataType</code> kennzeichnet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Metamodell-Schema ohne zeitlichen Ablauf oder Interaktionssequenzen. Es definiert strukturelle Mapping-Pfade für die Modelltransformation und Tracing-Validierung: Tracing verläuft stets typkonform zwischen korrespondierenden Abstraktionsebenen (<code>ApplicationDataType</code>), woran sich plattformintern die Auflösung via <code>DataTypeMap</code> anschließt. Ein direkter Brückenschlag unter Umgehung des plattformspezifischen <code>ApplicationDataType</code> ist ungültig.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsregel für AUTOSAR-Modellierer und Toolchain-Entwickler: Ein plattformunabhängiger <code>ApplicationDataType</code> der Abstract Platform darf nicht direkt auf einen plattformspezifischen <code>AbstractImplementationDataType</code> der Classic oder Adaptive Platform zurückgeführt werden (<code>&lt;&lt;tracing&gt;&gt;</code> verboten). Die Spezifikation erzwingt zwingend den Zwischenschritt über den plattformspezifischen <code>ApplicationDataType</code> und die anschließende plattformspezifische Typabbildung mittels <code>DataTypeMap</code>. Modell-Prüfwerkzeuge müssen direkte Tracing-Relationen zwischen abstrakten Anwendungsdatentypen und konkreten Implementierungsdatentypen als Konformitätsfehler ablehnen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1dd8938396b8a97d", "to": "FIG-617f2be197133249", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-617f2be197133249", "to": "FIG-1dd8938396b8a97d", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
